import { TouchableOpacity, Text } from 'react-native'
import { Copy } from 'lucide-react-native'
import { colors, Theme, useTheme } from '@/theme'
import { defineStyles } from '@/utils/defineStyles'
import * as Clipboard from 'expo-clipboard'
import { toast } from '@/utils/toast'
import { format, formatDistance, subMinutes } from 'date-fns'
import { Block, Message } from '../utils/types'
import {
	getModeKeyForAction,
	hasExtendedThinkingBlock,
	MODE_METADATA
} from '@/utils/mode-metadata'
import { AnimatePresence, MotiView } from 'moti'

const getActionLabel = (message: Message): string | null => {
	const { action } = message
	if (!action) return null
	const modeKey = getModeKeyForAction({
		action,
		hasExtendedThinking: hasExtendedThinkingBlock(message.blocks)
	})
	if (!modeKey) return null
	return MODE_METADATA[modeKey].label
}

const dateFormatter = Intl.DateTimeFormat('en-US', {
	month: 'short',
	day: '2-digit',
	hour: 'numeric',
	minute: '2-digit',
	hour12: true
})

const formatDate = (datetime: number | Date): string =>
	dateFormatter.format(new Date(datetime))

const getFormattedTime = (date: Date) => {
	// if less than 1 minute ago
	if (subMinutes(new Date(), 1) < date) {
		return 'Just now'
	}
	// if less than 60 minutes ago
	if (subMinutes(new Date(), 60) < date) {
		return formatDistance(date, new Date(), {
			addSuffix: true
		})
	}
	// if this is today, just show the time
	if (new Date().getDate() === date.getDate()) {
		return format(date, 'p')
	}
	// if this was any day before today
	return formatDate(date)
}

export const ChatFooterContainer = ({ message }: { message: Message }) => {
	const { theme } = useTheme()

	const isUser = message.actor === 'user'
	const isAssistant = message.actor === 'assistant'
	const actionLabel = getActionLabel(message)

	const copyMessageToClipboard = async () => {
		const messageToCopy = message.blocks
			.filter(
				(block): block is Block & { type: 'text' } => block.type === 'text'
			)
			.map((block) => block.code)
			.join('\n')
		await Clipboard.setStringAsync(messageToCopy)
		toast.show({
			message: 'Message copied!',
			variant: 'success'
		})
	}

	if (!message.revision) return null

	return (
		<AnimatePresence>
			<MotiView
				from={{ opacity: 0, translateY: 10 }}
				animate={{ opacity: 1, translateY: 0 }}
				exit={{ opacity: 0, translateY: 10 }}
				transition={{
					type: 'timing',
					duration: 300
				}}
				style={[styles.actionsContainer, isUser && { alignSelf: 'flex-end' }]}
			>
				<TouchableOpacity
					style={styles.copyButton}
					onPress={copyMessageToClipboard}
				>
					<Copy size={18} color={colors[theme].gray[400]} />
				</TouchableOpacity>
				{isAssistant && (
					<>
						<Text style={styles.timeStampText(theme)}>
							{getFormattedTime(message.revision.createdAt ?? new Date())}
						</Text>
						{actionLabel && (
							<>
								<Text style={styles.timeStampText(theme)}> · </Text>
								<Text style={styles.timeStampText(theme)}>{actionLabel}</Text>
							</>
						)}
					</>
				)}
			</MotiView>
		</AnimatePresence>
	)
}

const styles = defineStyles({
	actionsContainer: {
		flexDirection: 'row',
		alignItems: 'center',
		paddingLeft: 28,
		gap: 4
	},
	copyButton: {
		padding: 4,
		borderRadius: 50
	},
	timeStampText: (theme: Theme) => ({
		fontSize: 14,
		fontWeight: '500',
		color: colors[theme].gray[400]
	})
})
